<script setup lang="ts">
import { computed, ref } from 'vue'
import { Setting, Brush, FolderOpened, Check } from '@element-plus/icons-vue'
import type { StudioSettings } from '../../electron/shared/local-ai-studio'
import { normalizeAppearance, appearanceDefaults, type AppAppearance } from '../../electron/shared/app-appearance'
import { LOCAL_AI_MAX_OUTPUT_TOKENS } from '../../electron/shared/local-ai'
import AppearanceBackground from './AppearanceBackground.vue'
const props = defineProps<{ settings: StudioSettings; hfToken: string; busy: boolean; saving: boolean }>()
const emit = defineEmits<{ save: []; directory: []; clearToken: []; service: []; 'update:hfToken': [value: string] }>()
const menus = [
  { id: 'general', name: '常规', description: '新会话默认值与生成参数', icon: Setting },
  { id: 'appearance', name: '外观', description: '配色、字体与显示效果', icon: Brush },
  { id: 'storage', name: '模型与下载', description: '模型目录与下载凭据', icon: FolderOpened },
] as const
const active = ref<'general' | 'appearance' | 'storage'>('general')
const page = computed(() => menus.find(menu => menu.id === active.value)!)
const appearance = computed(() => normalizeAppearance(props.settings.appearance))
function setAppearance<K extends keyof AppAppearance>(key: K, value: AppAppearance[K]) {
  props.settings.appearance = normalizeAppearance({ ...appearance.value, [key]: value })
}
const themes = [{ id: 'minimal', name: '素白', color: '#526174' }, { id: 'ocean', name: '晴海', color: '#326d9a' }, { id: 'paper', name: '暖砂', color: '#96623e' }, { id: 'terminal', name: '青岚', color: '#34796b' }] as const
const colors = [{key:'accentColor',name:'强调色',description:'按钮、选中项和焦点',fallback:'#3478c6'}, {key:'backgroundColor',name:'背景色',description:'页面与面板底色',fallback:'#ffffff'}, {key:'foregroundColor',name:'前景色',description:'正文与次要文字',fallback:'#222222'}] as const
function resetAppearance() {
  Object.assign(props.settings, { appearance: { ...appearanceDefaults }, theme: 'system', appearanceStyle: 'minimal', backgroundImage: '', backgroundOpacity: .15 })
}
</script>

<template>
  <main class="app-preferences settings-page">
    <aside class="preferences-nav" aria-label="设置分类"><strong>设置</strong><button v-for="menu in menus" :key="menu.id" :data-settings-menu="menu.id" :aria-current="active===menu.id?'page':undefined" @click="active=menu.id"><component :is="menu.icon"/><span>{{ menu.name }}</span></button><small>更改后点击保存设置</small></aside>
    <section class="preferences-content">
      <header class="page-intro"><div><h1>{{ page.name }}</h1><p>{{ page.description }}</p></div><button class="primary-button" :disabled="busy" @click="emit('save')"><Check/>{{ saving?'保存中…':'保存设置' }}</button></header>
      <div v-if="active==='general'" class="preferences-sections">
        <section class="preference-card"><h2>新会话默认值</h2><label class="field">系统提示词<textarea v-model="settings.systemPrompt" rows="5" maxlength="12000" placeholder="例如：使用中文，回答简洁，并给出必要示例。"/></label><p class="hint">作为新会话的默认系统提示词。</p></section>
        <section class="preference-card"><h2>生成参数</h2><div class="field-grid"><label class="field">Temperature<input v-model.number="settings.temperature" type="number" min="0" max="2" step="0.05"/></label><label class="field">最大输出 tokens<input v-model.number="settings.maxTokens" type="number" min="128" :max="LOCAL_AI_MAX_OUTPUT_TOKENS" step="128"/></label><label class="field">Top P<input v-model.number="settings.topP" type="number" min="0.01" max="1" step="0.01"/></label><label class="field">重复惩罚<input v-model.number="settings.repeatPenalty" type="number" min="0.1" max="2" step="0.05"/></label></div><p class="hint">DeepSeek 推荐默认 65,536；快速 Agent 单轮使用 8,192。实际输出预算不超过有效上下文的一半，参数支持取决于所用模型服务。</p></section>
        <section class="preference-card"><h2>模型性能小窗</h2><label class="check-row"><span><strong>显示 Token 速度</strong><small>查看本地模型处理速度、外部模型请求吞吐及状态。</small></span><input v-model="settings.showTokenSpeed" type="checkbox" aria-label="显示 Token 速度"/></label><p class="hint">开启后直接打开独立窗口，点击“保存设置”后下次启动自动打开。本地模型使用 llama-server 实测日志；外部 API 使用请求计时和 Token 用量，流式阶段显示粗估。</p></section>
        <section class="preference-card"><h2>对话执行检查器</h2><label class="check-row"><span><strong>显示执行检查器</strong><small>查看能力、工具、插件调用，AI 输出及执行入参；支持暂停后改参。</small></span><input v-model="settings.showExecutionInspector" type="checkbox" aria-label="显示执行检查器"/></label><label class="check-row" style="margin-top:16px"><span><strong>新一轮对话在首次调用前暂停</strong><small>开启后可单步检查后续调用，或应用参数并连续运行。</small></span><input v-model="settings.pauseBeforeAgentCalls" :disabled="!settings.showExecutionInspector" type="checkbox" aria-label="首次调用前暂停"/></label><p class="hint">开启后直接打开独立窗口；保存设置后下次启动自动打开。自动暂停设置从下一轮对话生效。可拖动系统标题栏移动、拖动窗口边框缩放。暂停或等待暂停时，先继续或停止对话才能关闭设置开关。</p></section>
        <section class="preference-card link-card"><div><h2>模型连接</h2><p class="hint">远程 API、本地模型与服务连接统一在模型服务中管理。</p></div><button @click="emit('service')">前往模型服务 →</button></section>
      </div>
      <div v-else-if="active==='appearance'" class="preferences-sections">
        <p class="appearance-note">修改后即时预览，保存后下次启动仍会使用。</p>
        <section class="preference-card"><h2>模式与主题</h2><label class="field">模式<select v-model="settings.theme" aria-label="外观模式"><option value="system">跟随系统</option><option value="light">浅色（Light）</option><option value="dark">深色（Dark）</option></select></label><span class="field-label">主题</span><div class="theme-options" role="group" aria-label="界面风格"><button v-for="theme in themes" :key="theme.id" :aria-pressed="settings.appearanceStyle===theme.id" @click="settings.appearanceStyle=theme.id"><i :style="{background:theme.color}"/>{{ theme.name }}<Check v-if="settings.appearanceStyle===theme.id"/></button></div></section>
        <section class="preference-card"><h2>颜色</h2><p class="hint">默认随主题变化，也可单独设置。</p><div v-for="color in colors" :key="color.key" class="color-row"><div><strong>{{ color.name }}</strong><small>{{ color.description }}</small></div><div class="color-controls"><input type="color" :value="appearance[color.key] || color.fallback" :aria-label="color.name" @input="setAppearance(color.key,($event.target as HTMLInputElement).value)"/><code>{{ appearance[color.key] || '跟随主题' }}</code><button :disabled="!appearance[color.key]" :aria-label="`重置${color.name}`" @click="setAppearance(color.key,'')">重置</button></div></div></section>
        <section class="preference-card"><h2>背景图片</h2><AppearanceBackground :image="settings.backgroundImage" :opacity="settings.backgroundOpacity" @change="Object.assign(settings,$event)"/></section>
        <section class="preference-card"><h2>字体与排版</h2><div class="field-grid"><label class="field">界面字体<select :value="appearance.fontFamily" aria-label="界面字体" @change="setAppearance('fontFamily',($event.target as HTMLSelectElement).value)"><option value="system">系统默认</option><option value="sans">无衬线 · Arial / 微软雅黑</option><option value="serif">衬线 · Georgia / 宋体</option></select></label><label class="field">界面字号（px）<input type="number" min="12" max="18" :value="appearance.fontSize" aria-label="界面字号" @change="setAppearance('fontSize',Number(($event.target as HTMLInputElement).value))"/></label><label class="field">代码字体<select :value="appearance.codeFontFamily" aria-label="代码字体" @change="setAppearance('codeFontFamily',($event.target as HTMLSelectElement).value)"><option value="cascadia">Cascadia Code</option><option value="consolas">Consolas</option><option value="monospace">系统等宽字体</option></select></label><label class="field">代码字号（px）<input type="number" min="11" max="22" :value="appearance.codeFontSize" aria-label="代码字号" @change="setAppearance('codeFontSize',Number(($event.target as HTMLInputElement).value))"/></label><label class="field">代码行距<select :value="appearance.codeLineHeight" aria-label="代码行距" @change="setAppearance('codeLineHeight',Number(($event.target as HTMLSelectElement).value))"><option :value="1.4">紧凑 · 1.4</option><option :value="1.7">标准 · 1.7</option><option :value="2">宽松 · 2.0</option></select></label></div><p class="hint">未安装的字体会回退到本机可用字体。</p><div class="font-preview"><strong>界面预览 Aa 你好</strong><p>清晰的文字，让阅读更舒适。</p><pre>function greet(name) {
  return `Hello, ${name}`
}</pre></div></section>
        <section class="preference-card"><h2>其它</h2><label class="check-row"><span><strong>减少动态效果</strong><small>关闭界面动画和过渡；系统的减少动态效果设置始终优先。</small></span><input type="checkbox" :checked="appearance.reduceMotion" aria-label="减少动态效果" @change="setAppearance('reduceMotion',($event.target as HTMLInputElement).checked)"/></label><button class="reset-appearance" @click="resetAppearance">恢复默认外观</button></section>
      </div>
      <div v-else class="preferences-sections">
        <section class="preference-card"><h2>模型存储</h2><label class="field">下载目录<div class="path-field"><input v-model="settings.downloadDirectory" placeholder="选择模型保存目录"/><button :disabled="busy" aria-label="选择下载目录" @click="emit('directory')"><FolderOpened/></button></div></label><p class="hint">修改目录只影响新任务；现有模型和未完成下载仍使用原位置。</p></section>
        <section class="preference-card"><h2>Hugging Face</h2><label class="field">访问 Token<input :value="hfToken" type="password" autocomplete="new-password" :placeholder="settings.hasHfToken?'已安全保存，留空不修改':'公开模型通常不需要 Token'" @input="emit('update:hfToken',($event.target as HTMLInputElement).value)"/></label><button v-if="settings.hasHfToken" :disabled="busy" @click="emit('clearToken')">移除已保存的 Token</button><p class="hint">凭据使用操作系统安全存储加密；下载支持暂停、恢复和关闭应用后续传。</p></section>
      </div>
    </section>
  </main>
</template>

<style scoped>
